import React, { useEffect, useState, useRef } from 'react';
import { Mail, Phone, Github, Linkedin, Twitter } from 'lucide-react';
import image from '../assets/'

export default function HeroSection() {
  const [scrollY, setScrollY] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const [clickedSocial, setClickedSocial] = useState(null);
  const sectionRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll);

    // Intersection Observer for scroll animations
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 },
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    // Trigger initial animation
    const timer = setTimeout(() => setIsVisible(true), 300);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      observer.disconnect();
      clearTimeout(timer);
    };
  }, []);

  const handleSocialClick = (platform) => {
    setClickedSocial(platform);
    setTimeout(() => setClickedSocial(null), 300);
  };

  return (
    <section ref={sectionRef} className="relative min-h-screen overflow-hidden ">
      {/* Spline 3D Background with Parallax */}
      <div
        className="absolute inset-0 w-full h-full"
        style={{
          transform: `translateY(${scrollY * 0.5}px)`,
        }}
      >
        <iframe
          src="https://my.spline.design/cubes-A0T7CP5J2qsawolli9BlhInB/"
          className="w-full h-full border-0"
          title="3D Cubes Scene"
        />
        <div className="absolute inset-0 pointer-events-none">
          <div
            className="absolute inset-0"
            style={{
              background: `
                linear-gradient(
                  135deg,
                  rgba(0, 0, 0, 0.7) 0%,
                  rgba(0, 0, 0, 0.4) 50%,
                  rgba(0, 0, 0, 0.8) 100%
                )
              `,
            }}
          />
        </div>
      </div>

      {/* Floating Elements */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div
          className={`absolute top-20 left-10 w-2 h-2 bg-teal-400 rounded-full transition-all duration-1000 ${
            isVisible ? 'opacity-60 animate-pulse' : 'opacity-0'
          }`}
          style={{
            transform: `translateY(${scrollY * 0.3}px)`,
          }}
        />
        <div
          className={`absolute top-40 right-20 w-1 h-1 bg-white rounded-full transition-all duration-1200 delay-300 ${
            isVisible ? 'opacity-40 animate-bounce' : 'opacity-0'
          }`}
          style={{
            transform: `translateY(${scrollY * 0.7}px)`,
          }}
        />
        <div
          className={`absolute bottom-40 left-1/4 w-1.5 h-1.5 bg-teal-300 rounded-full transition-all duration-1400 delay-600 ${
            isVisible ? 'opacity-50 animate-ping' : 'opacity-0'
          }`}
          style={{
            transform: `translateY(${scrollY * 0.4}px)`,
          }}
        />
      </div>

      {/* Content */}
      <div className="relative z-10 container mx-auto px-6 lg:px-16 min-h-screen flex items-center">
        <div className="w-full max-w-7xl mx-auto">
          {/* Top Section - Small paragraph and big name */}
          <div className="mb-12">
            {/* Small paragraph with slide-in animation */}
            <div className="overflow-hidden">
              <p
                className={`text-gray-400 text-lg mb-4 transform transition-all duration-1000 delay-200 ${
                  isVisible ? 'translate-y-0 opacity-100' : 'translate-y-8 opacity-0'
                }`}
              >
                Hey👋, I'm a Full Stack Developer
              </p>
            </div>

            {/* Large name with staggered letter animation */}
            <div className="overflow-hidden">
              <h1
                className={`text-6xl lg:text-8xl xl:text-9xl font-bold gradient-text leading-none transform transition-all duration-1200 delay-500 ${
                  isVisible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-12 opacity-0 scale-95'
                }`}
                style={{
                  transform: `translateY(${scrollY * 0.1}px)`,
                }}
              >
                BADR EDDINE DIYAF
              </h1>
            </div>
          </div>

          {/* Main Content Grid */}
          <div className="grid lg:grid-cols-3 gap-12 items-start">
            {/* Left Column - Contact Info */}
            <div
              className={`space-y-6 transform transition-all duration-1000 delay-700 ${
                isVisible ? 'translate-x-0 opacity-100' : '-translate-x-8 opacity-0'
              }`}
            >
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2 group cursor-pointer hover:scale-105 transition-transform duration-300">
                  <Mail className="h-4 w-4 text-teal-500 group-hover:animate-bounce" />
                  <span className="text-white group-hover:text-teal-400 transition-colors duration-300">
                    info@badreddine.com
                  </span>
                </div>
                <div className="flex items-center gap-2 group cursor-pointer hover:scale-105 transition-transform duration-300">
                  <Phone className="h-4 w-4 text-teal-500 group-hover:animate-bounce" />
                  <span className="text-white group-hover:text-teal-400 transition-colors duration-300">
                    +1 234 567 890
                  </span>
                </div>
              </div>
            </div>

            {/* Center Column - Image */}
            <div
              className={`flex justify-center transform transition-all duration-1200 delay-900 ${
                isVisible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-12 opacity-0 scale-95'
              }`}
            >
              <div className="relative w-full max-w-sm group">
                <div
                  className="relative rounded-2xl overflow-hidden bg-black/20 backdrop-blur-sm border border-white/10 hover:border-teal-500/50 transition-all duration-500 hover:scale-105 hover:shadow-2xl hover:shadow-teal-500/20"
                  style={{
                    transform: `translateY(${scrollY * -0.1}px)`,
                  }}
                >
                  <img
                    src={image}
                    alt="Badr Eddine Diyaf"
                    className="w-full h-auto rounded-2xl grayscale group-hover:grayscale-0 transition-all duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent group-hover:from-black/40 transition-all duration-500"></div>

                  {/* Social Icons Inside Image */}
                  <div className="absolute bottom-6 left-6 flex gap-3 opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                    <a
                      href="https://github.com"
                      onClick={() => handleSocialClick('github')}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-teal-500 hover:bg-teal-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 ${
                        clickedSocial === 'github' ? 'animate-pulse scale-125' : ''
                      }`}
                    >
                      <Github className="w-4 h-4 text-white" />
                    </a>
                    <a
                      href="https://linkedin.com"
                      onClick={() => handleSocialClick('linkedin')}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-teal-500 hover:bg-teal-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 ${
                        clickedSocial === 'linkedin' ? 'animate-pulse scale-125' : ''
                      }`}
                    >
                      <Linkedin className="w-4 h-4 text-white" />
                    </a>
                    <a
                      href="https://x.com"
                      onClick={() => handleSocialClick('twitter')}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-teal-500 hover:bg-teal-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 ${
                        clickedSocial === 'twitter' ? 'animate-pulse scale-125' : ''
                      }`}
                    >
                      <Twitter className="w-4 h-4 text-white" />
                    </a>
                  </div>

                  {/* Animated border on hover */}
                  <div className="absolute inset-0 rounded-2xl border-2 border-teal-500/0 group-hover:border-teal-500/30 transition-all duration-500"></div>
                </div>

                {/* Floating indicator */}
                <div className="absolute -top-2 -right-2 w-4 h-4 bg-teal-400 rounded-full animate-ping opacity-75 group-hover:opacity-0 transition-opacity duration-300"></div>
              </div>
            </div>

            {/* Right Column - Description and Social Links */}
            <div
              className={`space-y-8 transform transition-all duration-1000 delay-1100 ${
                isVisible ? 'translate-x-0 opacity-100' : 'translate-x-8 opacity-0'
              }`}
            >
              <p
                className="text-lg text-gray-400 leading-relaxed hover:text-gray-300 transition-colors duration-300"
                style={{
                  transform: `translateY(${scrollY * 0.05}px)`,
                }}
              >
                I build fast, scalable, and user-friendly web applications using modern JavaScript frameworks —
                combining React on the frontend and Node.js on the server-side.
              </p>

              {/* Social Media Links with staggered animations */}
              <div className="space-y-3">
                {[
                  { href: 'https://x.com', label: 'Twitter (X)', key: 'twitter-link' },
                  { href: 'https://linkedin.com', label: 'LinkedIn', key: 'linkedin-link' },
                  { href: 'https://github.com', label: 'GitHub', key: 'github-link' },
                  { href: 'https://codepen.io', label: 'CodePen', key: 'codepen-link' },
                ].map((social, index) => (
                  <a
                    key={social.key}
                    href={social.href}
                    onClick={() => handleSocialClick(social.key)}
                    className={`flex items-center gap-2 text-gray-400 hover:text-teal-500 transition-all duration-300 text-sm group hover:scale-105 transform ${
                      isVisible ? 'translate-x-0 opacity-100' : 'translate-x-4 opacity-0'
                    } ${clickedSocial === social.key ? 'scale-110 text-teal-400' : ''}`}
                    style={{
                      transitionDelay: `${1300 + index * 100}ms`,
                    }}
                  >
                    <span className="group-hover:scale-125 transition-transform duration-300">/</span>
                    <span className="group-hover:text-teal-500">{social.label}</span>
                  </a>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <div
        className={`absolute bottom-8 left-1/2 transform -translate-x-1/2 transition-all duration-1000 delay-1500 ${
          isVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'
        }`}
      >
        <div className="w-6 h-10 border-2 border-gray-600 rounded-full flex justify-center hover:border-teal-500 transition-colors duration-300 cursor-pointer">
          <div className="w-0.5 h-3 bg-teal-400 rounded-full mt-2 animate-bounce"></div>
        </div>
      </div>
    </section>
  );
}
